fn rotate_right(list: &Vec<u32>, n: usize) -> Vec<u32> {
    let len = list.len();
    // Since the problem guarantees `list` is non-empty, `len > 0`.
    let shift = n % len;
    // Compute split index s = len - (n mod len)
    let s = len - shift;

    // Build the rotated vector
    let mut new_list = Vec::with_capacity(len);
    // Append the suffix from s..len
    new_list.extend_from_slice(&list[s..]);
    // Then append the prefix from 0..s
    new_list.extend_from_slice(&list[..s]);

    new_list
}

